"use client";

import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { clsx } from "clsx";
import type { ComponentPropsWithRef, ReactElement, ReactNode, RefObject } from "react";

import "./dialog.css";

export type DialogOpenChangeReason =
  | "trigger"
  | "outside"
  | "escape"
  | "close"
  | "focus-out"
  | "programmatic";

export type DialogOpenChangeDetails = Readonly<{
  cancel: () => void;
  event: Event;
  reason: DialogOpenChangeReason;
}>;

export type DialogProps = Readonly<{
  children?: ReactNode;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean, details: DialogOpenChangeDetails) => void;
  open?: boolean;
}>;

function mfdOpenChangeReason(reason: string): DialogOpenChangeReason {
  switch (reason) {
    case "trigger-press":
      return "trigger";
    case "outside-press":
      return "outside";
    case "escape-key":
      return "escape";
    case "close-press":
      return "close";
    case "focus-out":
      return "focus-out";
    default:
      return "programmatic";
  }
}

export function Dialog({ children, defaultOpen, onOpenChange, open }: DialogProps) {
  return (
    <BaseDialog.Root
      defaultOpen={defaultOpen}
      onOpenChange={(nextOpen, details) =>
        onOpenChange?.(nextOpen, {
          cancel: details.cancel,
          event: details.event,
          reason: mfdOpenChangeReason(details.reason),
        })
      }
      open={open}
    >
      {children}
    </BaseDialog.Root>
  );
}

type DialogButtonProps = Omit<ComponentPropsWithRef<"button">, "children"> & {
  children?: ReactNode;
  render?: ReactElement<Record<string, unknown>>;
};

export type DialogTriggerProps = DialogButtonProps;

export function DialogTrigger(props: DialogTriggerProps) {
  return <BaseDialog.Trigger {...props} />;
}

export type DialogCloseProps = DialogButtonProps;

export function DialogClose(props: DialogCloseProps) {
  return <BaseDialog.Close {...props} />;
}

export type DialogTitleProps = ComponentPropsWithRef<"h2">;

export function DialogTitle(props: DialogTitleProps) {
  return <BaseDialog.Title {...props} />;
}

export type DialogDescriptionProps = ComponentPropsWithRef<"p">;

export function DialogDescription(props: DialogDescriptionProps) {
  return <BaseDialog.Description {...props} />;
}

export type DialogInteractionType = "mouse" | "touch" | "pen" | "keyboard" | "unknown";
type DialogFocusTarget =
  | boolean
  | RefObject<HTMLElement | null>
  | ((interactionType: DialogInteractionType) => boolean | HTMLElement | null | undefined);

export type DialogContentProps = Omit<ComponentPropsWithRef<"div">, "size"> & {
  closeDisabled?: boolean;
  finalFocus?: DialogFocusTarget;
  initialFocus?: DialogFocusTarget;
  size?: "sm" | "md" | "lg";
};

function baseFocusTarget(focus: DialogFocusTarget | undefined) {
  if (typeof focus !== "function") {
    return focus;
  }
  return (interactionType: "mouse" | "touch" | "pen" | "keyboard" | "") =>
    focus(interactionType || "unknown");
}

export function DialogContent({
  children,
  className,
  closeDisabled = false,
  finalFocus,
  initialFocus,
  size = "md",
  ...props
}: DialogContentProps) {
  return (
    <BaseDialog.Portal>
      <BaseDialog.Backdrop className="mfd-dialog__backdrop" />
      <BaseDialog.Viewport className="mfd-dialog__viewport">
        <BaseDialog.Popup
          {...props}
          className={clsx("mfd-dialog__content", className)}
          data-size={size}
          finalFocus={baseFocusTarget(finalFocus)}
          initialFocus={baseFocusTarget(initialFocus)}
        >
          {children}
          <BaseDialog.Close
            aria-label="Close"
            className="mfd-dialog__close"
            disabled={closeDisabled}
          >
            <span aria-hidden="true">×</span>
          </BaseDialog.Close>
        </BaseDialog.Popup>
      </BaseDialog.Viewport>
    </BaseDialog.Portal>
  );
}

export type DialogHeaderProps = ComponentPropsWithRef<"header">;

export function DialogHeader({ className, ...props }: DialogHeaderProps) {
  return <header {...props} className={clsx("mfd-dialog__header", className)} />;
}

export type DialogBodyProps = ComponentPropsWithRef<"div">;

export function DialogBody({ className, ...props }: DialogBodyProps) {
  return <div {...props} className={clsx("mfd-dialog__body", className)} />;
}

export type DialogFooterProps = ComponentPropsWithRef<"footer">;

export function DialogFooter({ className, ...props }: DialogFooterProps) {
  return <footer {...props} className={clsx("mfd-dialog__footer", className)} />;
}

.mfd-dialog__backdrop {
  background: var(--mfd-color-overlay-backdrop);
  inset: 0;
  position: fixed;
  transition: opacity var(--mfd-motion-duration-moderate) var(--mfd-motion-easing-standard);
}

.mfd-dialog__viewport {
  align-items: center;
  display: grid;
  inset: 0;
  justify-items: center;
  padding: var(--mfd-space-stack-lg);
  position: fixed;
}

.mfd-dialog__content {
  background: var(--mfd-color-bg-surface);
  border: 1px solid var(--mfd-color-border-subtle);
  border-radius: var(--mfd-radius-surface);
  box-shadow: var(--mfd-elevation-modal);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  max-block-size: min(44rem, calc(100svh - 2 * var(--mfd-space-stack-lg)));
  max-inline-size: 100%;
  position: relative;
  transition:
    opacity var(--mfd-motion-duration-moderate) var(--mfd-motion-easing-standard),
    transform var(--mfd-motion-duration-moderate) var(--mfd-motion-easing-standard);
  width: 100%;
}

.mfd-dialog__content[data-size="sm"] {
  width: min(100%, 28rem);
}

.mfd-dialog__content[data-size="md"] {
  width: min(100%, 36rem);
}

.mfd-dialog__content[data-size="lg"] {
  width: min(100%, 48rem);
}

.mfd-dialog__header,
.mfd-dialog__body,
.mfd-dialog__footer {
  padding: var(--mfd-space-stack-lg);
}

.mfd-dialog__header {
  padding-inline-end: calc(var(--mfd-space-inline-lg) * 3);
}

.mfd-dialog__header h2,
.mfd-dialog__header p {
  margin: 0;
}

.mfd-dialog__header h2 {
  font:
    var(--mfd-typography-heading-font-weight) var(--mfd-typography-heading-font-size) /
    var(--mfd-typography-heading-line-height) var(--mfd-typography-heading-font-family);
  letter-spacing: var(--mfd-typography-heading-letter-spacing);
}

.mfd-dialog__header p {
  color: var(--mfd-color-text-secondary);
  margin-block-start: var(--mfd-space-stack-xs);
}

.mfd-dialog__body {
  overflow-y: auto;
  padding-block: 0;
}

.mfd-dialog__footer {
  align-items: center;
  border-block-start: 1px solid var(--mfd-color-border-subtle);
  display: flex;
  gap: var(--mfd-space-inline-md);
  justify-content: flex-end;
}

.mfd-dialog__close {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: var(--mfd-radius-control);
  color: var(--mfd-color-text-secondary);
  cursor: pointer;
  display: inline-flex;
  font-size: 1.5rem;
  height: var(--mfd-size-hit-target-minimum);
  justify-content: center;
  position: absolute;
  inset-block-start: var(--mfd-space-stack-sm);
  inset-inline-end: var(--mfd-space-inline-sm);
  width: var(--mfd-size-hit-target-minimum);
}

.mfd-dialog__close:focus-visible {
  outline: 2px solid var(--mfd-color-border-focus);
  outline-offset: 2px;
}

@media (max-width: 639px) {
  .mfd-dialog__viewport {
    padding: 0;
  }

  .mfd-dialog__content,
  .mfd-dialog__content[data-size] {
    border: 0;
    border-radius: 0;
    height: 100svh;
    max-block-size: 100svh;
    width: 100%;
  }

  .mfd-dialog__footer {
    align-items: stretch;
    flex-direction: column-reverse;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mfd-dialog__backdrop,
  .mfd-dialog__content {
    transition: none;
  }
}
